import{_ as a,o as t,c as o,a0 as s}from"./chunks/framework.Bmhw_dvp.js";const h=JSON.parse('{"title":"Rullst Capital: SaaS Billing Made Easy","description":"","frontmatter":{},"headers":[],"relativePath":"guide/5-rullst-capital.md","filePath":"guide/5-rullst-capital.md"}'),i={name:"guide/5-rullst-capital.md"};function n(r,e,l,c,d,u){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="rullst-capital-saas-billing-made-easy" tabindex="-1">Rullst Capital: SaaS Billing Made Easy <a class="header-anchor" href="#rullst-capital-saas-billing-made-easy" aria-label="Permalink to &quot;Rullst Capital: SaaS Billing Made Easy&quot;">​</a></h1><p><strong>Rullst Capital</strong> is the billing and subscription orchestration layer for Rullst SaaS applications.</p><p>If you generated your project using the <code>SaaS</code> blueprint (<code>cargo rullst new</code> -&gt; Select <code>SaaS Starter</code>), your application already comes wired with Capital, allowing you to charge your users from day one.</p><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to &quot;Core Features&quot;">​</a></h2><ul><li><strong>Multi-Provider Support:</strong> Rullst Capital currently supports <code>Stripe</code> and <code>LemonSqueezy</code>. You can swap between them by simply changing the <code>BILLING_PROVIDER</code> environment variable. No code changes required!</li><li><strong>Webhook Handling:</strong> Secure webhook endpoints are automatically set up to listen to subscription updates, payment successes, and cancellations.</li><li><strong>Database Synchronization:</strong> When a payment succeeds, Capital automatically updates the <code>subscriptions</code> table in your local database via the <code>rullst-orm</code>, keeping user access in sync with their payment status.</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>In your <code>.env</code> file, configure your keys:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BILLING_PROVIDER=stripe # or lemonsqueezy</span></span>
<span class="line"><span>BILLING_API_KEY=sk_test_...</span></span>
<span class="line"><span>BILLING_WEBHOOK_SECRET=whsec_...</span></span></code></pre></div><h2 id="how-it-works-in-your-app" tabindex="-1">How It Works in Your App <a class="header-anchor" href="#how-it-works-in-your-app" aria-label="Permalink to &quot;How It Works in Your App&quot;">​</a></h2><p>The generated <code>billing_controller.rs</code> provides two primary endpoints:</p><ol><li><strong>Checkout Redirect:</strong> When a user clicks &quot;Upgrade to Pro&quot;, they hit <code>/billing/checkout?plan=price_pro</code>. Rullst Capital instantly communicates with Stripe/LemonSqueezy to create a secure checkout session and redirects the user.</li><li><strong>Webhook Listener:</strong> The <code>/billing/webhook</code> route securely verifies the signature of the incoming request and delegates it to the <code>webhook_handler</code>. The handler then updates the user&#39;s <code>plan_id</code> and <code>ends_at</code> timestamp in your local database.</li></ol><p>This architecture ensures your application stays extremely fast and never stores sensitive payment data on your servers.</p>`,12)])])}const g=a(i,[["render",n]]);export{h as __pageData,g as default};
